import json,re
for f in ['1.jsonl','50.jsonl','100.jsonl']:
    rows=[json.loads(l) for l in open(f)]
    agree=0;strict=0;mism=[]
    for r in rows:
        m=re.findall(r'#### (\-?[0-9\.,]+)',r['output'])
        ok=0
        if m:
            try: ok=float(m[-1].replace(',','').rstrip('.'))==float(r['gts'].replace(',',''))
            except: pass
        strict+=ok
        if bool(ok)==bool(r['score']>0): agree+=1
        else: mism.append(r)
    print(f,'logged',sum(r['score'] for r in rows)/len(rows),'strict',strict/len(rows),'agree',agree/len(rows))
    for r in mism[:2]: print('  MISMATCH score',r['score'],'gt',r['gts'],repr(r['output'][-150:]))
    print('  input tail',repr(rows[0]['input'][-200:]))
